import{_ as o,a0 as p,w as u,s as r,ao as x,I as i,x as n,a1 as l,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在Arch上使用Syslinux替代GRUB | LCTT x X-CMD","titleTemplate":false,"description":"在Arch上使用Syslinux替代GRUB | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Arch上使用Syslinux替代GRUB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Arch上使用Syslinux替代GRUB | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/How to Replace GRUB with Syslinux on Arch Linux","title":"在Arch上使用Syslinux替代GRUB","tag":"201402","desc":""},"relativePath":"201402/How to Replace GRUB with Syslinux on Arch Linux.md","filePath":"[post].md"}'),a={name:"201402/How to Replace GRUB with Syslinux on Arch Linux.md"};function y(d,t,S,f,m,R){const s=p("Link");return u(),r("div",null,[t[14]||(t[14]=x(`<h1 id="在arch上使用syslinux替代grub" tabindex="-1">在Arch上使用Syslinux替代GRUB <a class="header-anchor" href="#在arch上使用syslinux替代grub" aria-label="Permalink to “在Arch上使用Syslinux替代GRUB”">​</a></h1><p>这个教程用于教授Arch Linux用户如何在Arch下安装Syslinux——一个轻量级、快速并且现代感十足的系统引导程序，用来替换掉系统自带的GRUB引导程序。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Replace-GRUB-with-Syslinux-on-Arch-Linux-415394-2.jpg" alt=""></p><p>实际上，Syslinux不是一个简单的开机启动装载程序，它支持多种启动引导方式，本地载入，通过PXE网络载入，以及通过可移动媒体载入。并且，它还同时支持MBR和GPT磁盘，以及RAID设置。</p><p>在开始你实际操作之前，你应该知道Syslinux支持如下文件系统：FAT，EXT2，EXT3，EXT4和Btrfs，而且Syslinux能够运行在支持UEFI或BIOS的机器上。到目前为止，Syslinux还不能访问自己所在的分区之外的文件。</p><p>在你替换GRUB启动之前，请认真考虑，这只是一个可选的尝试，这个尝试有可能会给你带来一些麻烦。如果说你只是想感受一下新鲜的事物，或是已经厌倦了GRUB的界面，没问题来尝试尝试Syslinux吧。</p><p>###在Arch box 中安装Syslinux ###</p><p>该说的都说完了，下面我们来开始安装Syslinux，准备替换掉已有的GRUB或者GRUB2启动程序。打开一个终端，输入如下命令来安装Syslinux</p><pre><code>sudo pacman -S syslinux
</code></pre><p>安装完成后，你应该注意到一条消息，将指导您如何分别在BIOS或UEFI机器上部署Syslinux引导装载程序。BIOS用户比较幸运，因为他们只需要运行syslinux-install_update 脚本就行了，这个脚本是Matthew Gyurgyik编写的，用来在BIOS机器上成功的部署Syslinux。</p><p>###在Arch box上部署Syslinux###</p><p>如果你拥有的是一个单独的/boot分区，你要保证你是在/boot分区上执行的这个脚本。在终端中输入如下命令：</p><pre><code>sudo syslinux-install_update -i -a -m
</code></pre><p>这个脚本会安装必需的文件，并且用启动标记标记分区，同时会安装MBR引导代码。</p><p>###配置Syslinux###</p><p>这是非常非常重要的一步，任何人都不能忽略它，因为如果你的Syslinux没有正确的配置，你的电脑将不能启动。请再次注意。</p>`,16)),i("p",null,[t[1]||(t[1]=n("目前，Syslinux能通过/boot/syslinux/syslinux.cfg文件进行配置。在",-1)),l(s,{href:"https://wiki.archlinux.org/index.php/syslinux#Configuration"},{default:e(()=>[...t[0]||(t[0]=[n("the official Arch Linux page of Syslinux",-1)])]),_:1}),t[2]||(t[2]=n(" 中查看详细的配置指令。当你配置成功后，重启你的系统然后来看看新的启动引导程序效果如何！",-1))]),t[15]||(t[15]=i("p",null,"如果你有任何的问题，请毫不犹豫的在评论中提出！",-1)),t[16]||(t[16]=i("hr",null,null,-1)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),l(s,{href:"http://news.softpedia.com/news/How-to-Replace-GRUB-with-Syslinux-on-Arch-Linux-415394.shtml"},{default:e(()=>[...t[3]||(t[3]=[n("http://news.softpedia.com/news/How-to-Replace-GRUB-with-Syslinux-on-Arch-Linux-415394.shtml",-1)])]),_:1})]),i("p",null,[t[7]||(t[7]=n("译者：",-1)),l(s,{href:"https://github.com/dy2009"},{default:e(()=>[...t[5]||(t[5]=[n("dy2009",-1)])]),_:1}),t[8]||(t[8]=n(" 校对：",-1)),l(s,{href:"http://blog.csdn.net/tinyeyeser"},{default:e(()=>[...t[6]||(t[6]=[n("Mr小眼儿",-1)])]),_:1})]),i("p",null,[t[11]||(t[11]=n("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原创翻译，",-1)),l(s,{href:"http://linux.cn/"},{default:e(()=>[...t[10]||(t[10]=[n("Linux中国",-1)])]),_:1}),t[13]||(t[13]=n(" 荣誉推出",-1))])])}const A=o(a,[["render",y]]);export{T as __pageData,A as default};
